using System;using System.Linq;using UnityEngine;using UnityEditor;using Codice.Expedition;using Codice.Mechanics;using Codice.Characters;using Codice.UI;
public static class VerifyWorldThree {
 public static string Layouts(){for(int seed=1;seed<=256;seed++)for(int f=1;f<=9;f++){var l=new ExpeditionLayout(seed,f);if(!l.Connected()||l.Count<7||l.Count>10)throw new Exception("Layout "+seed+"/"+f);if(f==9&&(l.Width(l.Boss)<8||l.Radius(l.Boss)<8))throw new Exception("Arena too small");if(!Resources.Load<GameObject>(ExpeditionFloor.BossResource(seed,f)))throw new Exception("Missing boss "+f);}foreach(var n in new[]{"HeadSpider","Huntsman","Executioner","StrawReaper","Watcher"})if(!Resources.Load<GameObject>("ExpeditionEnemies/Cemetery/"+n))throw new Exception("Missing mob "+n);return "PASS 2304 layouts, nine stages, five cemetery monsters";}
 public static string Load(){EditorApplication.isPaused=false;MainMenuUI.UnlockCheats("jam");ExpeditionFloor.DebugSeed=431;RunNavigation.StartExpeditionTest(PlayerClass.Warrior,9);return "Loading 3-3 seed 431";}
 public static string Boss(){var r=RunDirector.Instance;var f=r.Expedition;for(int i=0;i<f.Layout.Boss;i++)f.Cleared[i]=true;var cc=r.Player.GetComponent<CharacterController>();cc.enabled=false;r.Player.transform.position=f.Center(f.Layout.Boss)-Vector3.forward*10;cc.enabled=true;r.Player.State.LaboratoryImmortal=true;return "Entering Necromancer arena";}
 public static string Inspect(){var r=RunDirector.Instance;var f=r.Expedition;var b=f.context.arena.ActiveBoss;if(!b)throw new Exception("No boss");var path=new UnityEngine.AI.NavMeshPath();if(!UnityEngine.AI.NavMesh.CalculatePath(b.transform.position,r.Player.transform.position,-1,path)||path.status!=UnityEngine.AI.NavMeshPathStatus.PathComplete)throw new Exception("Unreachable boss");Debug.Log("[WorldThree] Boss="+b.name+" summons="+b.LivingSummons+" state="+b.State);return "PASS "+b.name+" reachable; summons="+b.LivingSummons+"; renderers="+b.GetComponentsInChildren<Renderer>().Count(x=>x.enabled);}

 public static string KillBoss(){var f=RunDirector.Instance.Expedition;var b=f.context.arena.ActiveBoss;if(!b)throw new Exception("No boss");if(b.LivingSummons>8)throw new Exception("Summon cap exceeded");int summons=b.LivingSummons;b.ReceiveDamage(new DamageInfo{amount=999999,source=RunDirector.Instance.Player.gameObject});return "Killed boss with "+summons+" summons";}
 public static string Finish(){var f=RunDirector.Instance.Expedition;int alive=UnityEngine.Object.FindObjectsByType<Codice.Enemies.BasicEnemy>().Count(e=>e.IsAlive);if(!f.Finished||f.InEncounter||alive!=0)throw new Exception("Encounter cleanup failed: "+f.Finished+"/"+f.InEncounter+"/"+alive);return "PASS final completion and summon cleanup";}
 public static string MobRoom(){EditorApplication.isPaused=false;MainMenuUI.UnlockCheats("jam");ExpeditionFloor.DebugSeed=922;RunNavigation.StartExpeditionTest(PlayerClass.Warrior,7);return "Loading 3-1";}
 public static string EnterRoom(){var r=RunDirector.Instance;var f=r.Expedition;int room=Enumerable.Range(1,f.Layout.Boss-1).First(n=>n!=f.Layout.StatueRoom&&n!=f.Layout.MerchantRoom);var cc=r.Player.GetComponent<CharacterController>();cc.enabled=false;r.Player.transform.position=f.Center(room);cc.enabled=true;r.Player.State.LaboratoryImmortal=true;return "Room="+room;}
 public static string CheckMobs(){var es=UnityEngine.Object.FindObjectsByType<Codice.Enemies.BasicEnemy>();if(es.Length<3)throw new Exception("Too few enemies: "+es.Length);foreach(var e in es){var p=new UnityEngine.AI.NavMeshPath();if(!UnityEngine.AI.NavMesh.CalculatePath(e.transform.position,RunDirector.Instance.Player.transform.position,-1,p)||p.status!=UnityEngine.AI.NavMeshPathStatus.PathComplete)throw new Exception("Unreachable "+e.name);}return "PASS reachable cemetery encounter: "+string.Join(",",es.Select(e=>e.name));}
}


